    this.playClickSound();
    try {
      const sceneRoot = OverlayManager.getSceneRoot(this.sceneKey);
      if (sceneRoot) {
        const storyOverlay = sceneRoot.querySelector("#story-overlay");
        const mainContent = sceneRoot.querySelector("#main-content");
        if (storyOverlay) {
          storyOverlay.style.transition = "opacity 0.3s";
          storyOverlay.style.opacity = "0";
          storyOverlay.style.pointerEvents = "none";
          this.time.delayedCall(300, () => {
            try {
              if (storyOverlay && storyOverlay.style) {
                storyOverlay.style.display = "none";
              }
            } catch (e) {
            }
          });
        }
        if (mainContent) {
          mainContent.style.opacity = "1";
        }
      }
    } catch (e) {
      console.warn("[TitleScreen] dismissStory UI error:", e);
    }
    if (MobileManager.isMobile && !this.audioStarted) {
      this.tryPlayBackgroundMusic();
    }
