  /**
   * Check developer code input and trigger corresponding actions
   * Code 300: Warp to Final War Scene (최후의 전쟁)
   * Code 301: Warp to Final War Scene Phase 2 (최후의 전쟁 Phase 2)
   * Code 302: Warp to Final War Scene Phase 3 (최후의 전쟁 Phase 3 - 칠두수)
   * Code 777: Warp to Developer Village
   * Code 999: Start Boss Rush Mode
   */
  checkDevCode() {
    console.log(`[TitleScreen] Dev code buffer: ${this.devCodeBuffer}`);
    if (this.devCodeBuffer.endsWith("302")) {
      console.log("[TitleScreen] Dev code 302 detected - Warping to Final War Phase 3!");
      this.devCodeBuffer = "";
      this.warpToFinalWarPhase3();
      return;
    }
    if (this.devCodeBuffer.endsWith("301")) {
      console.log("[TitleScreen] Dev code 301 detected - Warping to Final War Phase 2!");
      this.devCodeBuffer = "";
      this.warpToFinalWarPhase2();
      return;
    }
    if (this.devCodeBuffer.endsWith("300")) {
      console.log("[TitleScreen] Dev code 300 detected - Warping to Final War!");
      this.devCodeBuffer = "";
      this.warpToFinalWar();
      return;
    }
    if (this.devCodeBuffer.endsWith("777")) {
      console.log("[TitleScreen] Dev code 777 detected - Warping to Developer Village!");
      this.devCodeBuffer = "";
      this.warpToDevVillage();
      return;
    }
    if (this.devCodeBuffer.endsWith("999")) {
      console.log("[TitleScreen] Dev code 999 detected - Starting Boss Rush!");
      this.devCodeBuffer = "";
      this.startBossRushMode();
      return;
    }
  }
