  /**
   * Check if a pending upgrade choice blocks level up
   * Returns true if player has pending upgrade at a level threshold they've already passed
   * This ensures player must choose an upgrade before leveling past upgrade thresholds
   */
  hasPendingUpgradeBlockingLevelUp() {
    if (this.isUpgradeChoicePending) return true;
    if (!this.hasChosenClass || this.classType === "NONE") return false;
    const isArcher = this.classType === "ARCHER";
    if (this.level >= 77) {
      if (isArcher && this.upgrades.archer_L77_choice === "NONE") {
        return true;
      }
      if (!isArcher && this.upgrades.warrior_L77_choice === "NONE") {
        return true;
      }
    }
    if (this.level >= 333) {
      if (isArcher && this.upgrades.archer_L333_choice === "NONE") {
        return true;
      }
      if (!isArcher && this.upgrades.warrior_L333_choice === "NONE") {
        return true;
      }
    }
    if (this.level >= 1004) {
      if (isArcher && this.upgrades.archer_L1004_choice === "NONE") {
        return true;
      }
      if (!isArcher && this.upgrades.warrior_L1004_choice === "NONE") {
        return true;
      }
    }
    return false;
  }
