function isFiniteNumber(value) {
  return Number.isFinite(value) && !Number.isNaN(value);
}
function safeClamp(value, min, max) {
  if (!isFiniteNumber(value)) return min;
  if (!isFiniteNumber(min)) min = 0;
  if (!isFiniteNumber(max)) max = 1e3;
  return Math.max(min, Math.min(max, value));
}
function safeAngle(x1, y1, x2, y2) {
  if (!isFiniteNumber(x1) || !isFiniteNumber(y1) || !isFiniteNumber(x2) || !isFiniteNumber(y2)) {
    return 0;
  }
  const angle = Math.atan2(y2 - y1, x2 - x1);
  return isFiniteNumber(angle) ? angle : 0;
}
function getBossProfile(bossType) {
  return BOSS_PATTERN_PROFILES[bossType] || BOSS_PATTERN_PROFILES.default;
}
