  /**
   * Assign unique skills based on monster type for Boss Rush mode
   * Each monster has 1-2 unique skills
   */
  assignBossRushSkills() {
    switch (this.baseType) {
      // Melee/Tank types - Knockback + Stun
      case "ghoul":
      case "corpse_warrior":
      case "corpse_boss_warrior":
      case "stone_guardian":
      case "iron_maiden_demon":
        this.canPushPlayer = true;
        this.canStunPlayer = true;
        break;
      // Agile/Assassin types - Warp + Knockback  
      case "spider":
      case "snake":
      case "bone_crawler":
      case "chain_phantom":
      case "shadow_fiend":
      case "shadow_lord":
        this.canWarpToPlayer = true;
        this.canPushPlayer = true;
        break;
      // Magic/Ranged types - Heal Reduction + Stun
      case "cultMage":
      case "neon_wraith":
      case "forbidden_treant":
      case "serpent_spirit":
        this.canReduceHealing = true;
        this.canStunPlayer = true;
        break;
      // Undead/Corrupted types - Heal Reduction + Knockback
      case "skeleton":
      case "corpse_fallen_angel":
      case "corpse_boss_fallen_angel":
      case "vengeful_corpse":
      case "bloody_corpse":
        this.canReduceHealing = true;
        this.canPushPlayer = true;
        break;
      // Hospital zombie types - Stun + Heal Reduction
      case "zombie_nurse":
      case "zombie_doctor":
      case "zombie_pharmacist":
      case "zombie_surgeon":
        this.canStunPlayer = true;
        this.canReduceHealing = true;
        break;
      // Demon Lords - All skills!
      case "balrog":
        this.canPushPlayer = true;
        this.canStunPlayer = true;
        this.canReduceHealing = true;
        this.canWarpToPlayer = true;
        break;
      // Default - Knockback only
      default:
        this.canPushPlayer = true;
        break;
    }
    if (this.bossRushRound >= 8) {
      this.canWarpToPlayer = true;
    }
    if (this.bossRushRound >= 10) {
      this.canReduceHealing = true;
      this.canStunPlayer = true;
    }
  }
