  /**
   * Show HP regeneration effect for EP6 final boss (bloody theme)
   */
  showEP6RegenEffect(amount) {
    for (let i = 0; i < 12; i++) {
      const particle = this.scene.add.circle(
        this.x + Phaser.Math.Between(-40, 40),
        this.y - 20 + Phaser.Math.Between(-30, 30),
        Phaser.Math.Between(5, 10),
        16724838,
        0.9
      );
      particle.setDepth(150);
      this.scene.tweens.add({
        targets: particle,
        y: particle.y - 50,
        alpha: 0,
        duration: 1e3 + Phaser.Math.Between(0, 400),
        onComplete: () => particle.destroy()
      });
    }
    const healText = this.scene.add.text(this.x, this.y - 80, `+${amount} HP (6%)`, {
      fontFamily: "RetroPixel",
      fontSize: "24px",
      color: "#ff3366",
      stroke: "#000000",
      strokeThickness: 4
    }).setOrigin(0.5).setDepth(151);
    this.scene.tweens.add({
      targets: healText,
      y: healText.y - 50,
      alpha: 0,
      duration: 1500,
      onComplete: () => healText.destroy()
    });
    this.setTint(16711782);
    this.scene.time.delayedCall(300, () => {
      if (!this.isDead) {
        this.setTint(3385958);
      }
    });
  }
  /**
   * Show small HP regeneration effect for per-second regen (1% per second)
   * Less flashy than burst regen effects
   */
  showPerSecRegenEffect(amount) {
    for (let i = 0; i < 3; i++) {
      const particle = this.scene.add.circle(
        this.x + Phaser.Math.Between(-25, 25),
        this.y - 10 + Phaser.Math.Between(-20, 20),
        Phaser.Math.Between(3, 6),
        6750054,
        0.7
      );
      particle.setDepth(150);
      this.scene.tweens.add({
        targets: particle,
        y: particle.y - 30,
        alpha: 0,
        duration: 600 + Phaser.Math.Between(0, 200),
        onComplete: () => particle.destroy()
      });
    }
  }
  /**
   * Show special aura effect for super boss
   */
  showSuperBossAura() {
    const aura = this.scene.add.circle(this.x, this.y, 100, 16737792, 0.3);
    aura.setDepth(this.depth - 1);
    this.scene.tweens.add({
      targets: aura,
      scaleX: { from: 1, to: 1.3 },
      scaleY: { from: 1, to: 1.3 },
      alpha: { from: 0.3, to: 0.1 },
      duration: 1e3,
      yoyo: true,
      repeat: -1
    });
    this.__superBossAura = aura;
    this.scene.events.on("update", () => {
      if (this.active && !this.isDead && aura.active) {
        aura.setPosition(this.x, this.y);
      } else if (aura.active) {
        aura.destroy();
      }
    });
  }
