const EPISODE_INTERLUDES = {
  3: EP3_INTERLUDES,
  4: EP4_INTERLUDES,
  5: EP5_INTERLUDES,
  6: EP6_INTERLUDES,
  7: EP7_INTERLUDES,
  8: EP8_INTERLUDES,
  9: EP9_INTERLUDES,
  10: EP10_INTERLUDES,
  11: EP11_INTERLUDES
};
function getLocalizedInterlude(episodeIndex, roundInEpisode) {
  const lang = getLanguage();
  const episodeData = EPISODE_INTERLUDES[episodeIndex];
  if (!episodeData) {
    return null;
  }
  const langData = episodeData[lang];
  if (!langData || !langData[roundInEpisode]) {
    const koData = episodeData["ko"];
    return (koData == null ? void 0 : koData[roundInEpisode]) || null;
  }
  return langData[roundInEpisode];
}
function getSpeakerLabel(speaker) {
  const lang = getLanguage();
  const labels = SPEAKER_LABELS[lang];
  return labels[speaker] || labels["Player"];
}
function getInterludeUILabels() {
  const lang = getLanguage();
  return INTERLUDE_UI_LABELS[lang];
}
