      angelStatue.moveSpeed = angelStatue.moveSpeed * 0.7;
      angelStatue.expReward = Math.floor(angelStatue.expReward * 0.3);
      angelStatue.isMiniBoss = false;
      angelStatue.enemyTier = "normal";
      angelStatue.enemyType = "fallen_angel_statue";
