  /**
   * Show Lucifer intro dialogue before boss fight
   */
  showLuciferIntroDialogue() {
    const dialogueLines = [
      { speaker: "Lucifer", text: "넘겨. 그러면 편해져." },
      { speaker: "Player", text: "편안함은 주권이 아니야." },
      { speaker: "Lucifer", text: "그럼 고통 속에서 증명해 봐." }
    ];
    let currentIndex = 0;
    const firstLine = dialogueLines[0];
    const uiHTML = `
      <div id="lucifer-intro-container" class="fixed inset-0 flex items-center justify-center pointer-events-auto z-[1100]" style="background: rgba(40,0,0,0.9);">
        <div class="game-pixel-container-red-900 p-6 max-w-lg w-96" style="background: linear-gradient(135deg, rgba(60,10,10,0.98) 0%, rgba(30,5,5,0.95) 100%); border: 3px solid rgba(200,50,50,0.8);">
          
          <div class="text-center mb-4">
            <span class="text-red-400 text-2xl font-bold" style="font-family: RetroPixel; text-shadow: 2px 2px 4px rgba(0,0,0,0.8);">⚔️ FINAL BATTLE ⚔️</span>
          </div>
          
          <div id="lucifer-intro-speaker" class="mb-3">
            <span class="text-red-400 font-bold text-lg" style="font-family: RetroPixel; text-shadow: 2px 2px 4px rgba(0,0,0,0.8);">
              😈 루시퍼
            </span>
          </div>
          
          <div id="lucifer-intro-text" class="mb-4">
            <p class="text-white text-lg leading-relaxed" style="font-family: RetroPixel; text-shadow: 1px 1px 3px rgba(0,0,0,0.8);">"${firstLine.text}"</p>
          </div>
          
          <div class="flex justify-end">
            <button id="lucifer-intro-next-btn" class="game-pixel-container-clickable-red-600 px-6 py-2 text-white font-bold" style="font-family: RetroPixel;">
              다음 ▶
            </button>
          </div>
          
        </div>
      </div>
    `;
    const sceneKey = "DungeonScene-LuciferIntro";
    OverlayManager.setHTML(sceneKey, uiHTML);
    const sceneRoot = OverlayManager.getSceneRoot(sceneKey);
    const nextBtn = sceneRoot == null ? void 0 : sceneRoot.querySelector("#lucifer-intro-next-btn");
    const handleNext = () => {
      currentIndex++;
      if (currentIndex >= dialogueLines.length) {
        OverlayManager.clear(sceneKey);
        return;
      }
      const line = dialogueLines[currentIndex];
      const speakerEl = sceneRoot == null ? void 0 : sceneRoot.querySelector("#lucifer-intro-speaker span");
      const textEl = sceneRoot == null ? void 0 : sceneRoot.querySelector("#lucifer-intro-text p");
      if (speakerEl) {
        if (line.speaker === "Lucifer") {
          speakerEl.textContent = "😈 루시퍼";
          speakerEl.className = "text-red-400 font-bold text-lg";
        } else {
          speakerEl.textContent = "🗡️ 사냥꾼";
          speakerEl.className = "text-cyan-300 font-bold text-lg";
        }
      }
      if (textEl) {
        textEl.textContent = `"${line.text}"`;
      }
    };
    if (nextBtn) {
      nextBtn.addEventListener("click", handleNext);
      nextBtn.addEventListener("touchend", (e) => {
        e.preventDefault();
        handleNext();
      });
    }
  }
