    const maxStacks = 3;
    const buffOptions = [
      {
        type: "speed_buff",
        getStacks: () => this.player.speedBuffStackCount,
        apply: () => this.player.applySpeedBuff(buffDuration)
      },
      {
        type: "attack_buff",
        getStacks: () => this.player.attackBuffStackCount,
        apply: () => this.player.applyAttackBuff(buffDuration)
      },
      {
        type: "invincibility_buff",
        getStacks: () => this.player.invincibilityBuffStackCount,
        apply: () => this.player.applyInvincibilityBuff(buffDuration)
      },
      {
        type: "damage_aura_buff",
        getStacks: () => this.player.damageAuraBuffStackCount,
        apply: () => this.player.applyDamageAuraBuff(buffDuration)
      }
    ];
    const intendedBuff = buffOptions.find((b) => b.type === intendedType);
    if (intendedBuff && intendedBuff.getStacks() < maxStacks) {
      intendedBuff.apply();
      return;
    }
    const availableBuffs = buffOptions.filter((b) => b.getStacks() < maxStacks);
    if (availableBuffs.length > 0) {
      const randomBuff = availableBuffs[Phaser.Math.Between(0, availableBuffs.length - 1)];
      randomBuff.apply();
    }
