    g.beginPath();
    g.moveTo(centerX - halfW, centerY - halfH);
    g.lineTo(centerX + halfW, centerY + halfH);
    g.strokePath();
    g.beginPath();
    g.moveTo(centerX + halfW, centerY - halfH);
    g.lineTo(centerX - halfW, centerY + halfH);
    g.strokePath();
    g.beginPath();
    g.moveTo(centerX, centerY - halfH);
    g.lineTo(centerX, centerY + halfH);
    g.strokePath();
    g.beginPath();
    g.moveTo(centerX - halfW, centerY);
    g.lineTo(centerX + halfW, centerY);
    g.strokePath();
    g.lineStyle(2.5, neonColor, neonAlpha * 0.9);
    g.strokeRect(centerX - halfW, centerY - halfH, width, height);
    return g;
