      this.player.maxHealth = 500 + 100 * 10;
      this.player.health = this.player.maxHealth;
      this.player.maxMana = 100 + 100 * 5;
      this.player.mana = this.player.maxMana;
      this.player.baseAtk = 10 + 100 * 2;
