  createReturnPortal() {
    const x = this.tileSize * 2;
    const y = this.mapHeight - this.tileSize * 2;
    const container = this.add.container(x, y);
    const portalRing = this.add.ellipse(0, 0, 80, 80, 10053375, 0.8);
    portalRing.setStrokeStyle(4, 13408767, 1);
    container.add(portalRing);
    const innerPortal = this.add.ellipse(0, 0, 55, 55, 6697932, 0.5);
    container.add(innerPortal);
    const iconText = this.add.text(0, 0, "🏠", {
      fontFamily: "RetroPixel",
      fontSize: "24px"
    }).setOrigin(0.5);
    container.add(iconText);
    const nameLabel = this.add.text(0, 55, "개발자 마을", {
      fontFamily: "RetroPixel",
      fontSize: "10px",
      color: "#cc99ff",
      stroke: "#000000",
      strokeThickness: 2
    }).setOrigin(0.5);
    container.add(nameLabel);
    container.setDepth(15);
    this.returnPortal = container;
    const zone = this.add.zone(x, y, 90, 90);
    this.physics.add.existing(zone, false);
    const zoneBody = zone.body;
    zoneBody.setAllowGravity(false);
    zoneBody.setImmovable(true);
    this.returnPortalZone = zone;
    this.tweens.add({
      targets: portalRing,
      scaleX: { from: 1, to: 1.1 },
      scaleY: { from: 1, to: 1.1 },
      alpha: { from: 0.8, to: 1 },
      duration: 700,
      yoyo: true,
      repeat: -1,
      ease: "Sine.easeInOut"
    });
  }
  spawnGreedBoss() {
    const spawnX = this.mapWidth / 2;
    const spawnY = this.tileSize * 4;
    const bossName = "💰 탐욕의 매니저 (Greed Manager) 💰";
    this.boss = new GenericBoss(this, spawnX, spawnY, "greed_demon");
    if (this.boss.meleeTrigger) {
      this.enemyMeleeTriggers.add(this.boss.meleeTrigger);
    }
    this.boss.on("bossDamage", (data) => {
      this.showBossDamageNumber(data.x, data.y, data.damage);
    });
    if (this.boss) {
      this.boss.maxHealth = 888;
      this.boss.health = 888;
      this.enemies.add(this.boss);
      this.bossHealTimer = this.time.addEvent({
        delay: 8e3,
        callback: () => {
          if (this.boss && this.boss.active && this.boss.health > 0) {
            this.boss.health = Math.min(this.boss.maxHealth, this.boss.health + 8);
            const healText = this.add.text(
              this.boss.x,
              this.boss.y - 80,
              "+8",
              {
                fontFamily: "RetroPixel",
                fontSize: "18px",
                color: "#ffd700",
                stroke: "#000000",
                strokeThickness: 3
              }
            ).setOrigin(0.5).setDepth(200);
            this.tweens.add({
              targets: healText,
              y: healText.y - 30,
              alpha: 0,
              duration: 1e3,
              onComplete: () => healText.destroy()
            });
          }
        },
        loop: true
      });
      this.boss.on("fireProjectile", (data) => {
        const projectile = new EnemyProjectile(
          this,
          data.x,
          data.y,
          data.angle,
          data.damage,
          data.speed
        );
        projectile.setTint(16766720);
        this.enemyProjectiles.add(projectile);
      });
      this.time.delayedCall(500, () => {
        const bossText = this.add.text(
          this.mapWidth / 2,
          80,
          `${bossName}`,
          {
            fontFamily: "RetroPixel",
            fontSize: "18px",
            color: "#ffd700",
            stroke: "#000000",
            strokeThickness: 4
          }
        ).setOrigin(0.5).setDepth(100);
        this.tweens.add({
          targets: bossText,
          alpha: { from: 0, to: 1 },
          duration: 500
        });
        this.time.delayedCall(5e3, () => {
          this.tweens.add({
            targets: bossText,
            alpha: 0,
            duration: 500,
            onComplete: () => bossText.destroy()
          });
        });
      });
      this.boss.displayName = bossName;
      this.events.emit("bossSpawned", this.boss);
      console.log("[GreedScene] Boss spawned - emitted bossSpawned event for HP bar");
    }
    console.log(`[GreedScene] Spawned boss: ${bossName}`);
  }
