  /**
   * Open the settings menu
   * AUTO-PAUSES the game when menu opens
   */
  openMenu() {
    const sceneRoot = OverlayManager.getSceneRoot(this.sceneKey);
    if (!sceneRoot) return;
    const menuOverlay = sceneRoot.querySelector("#menu-overlay");
    if (!menuOverlay) return;
    this.isMenuOpen = true;
    menuOverlay.classList.remove("hidden");
    if (this.menuButtonElement) {
      this.menuButtonElement.style.display = "none";
    }
    if (this.currentGameSceneKey) {
      const gameScene = this.scene.get(this.currentGameSceneKey);
      if (gameScene && !gameScene.scene.isPaused()) {
        gameScene.scene.pause();
        console.log("[UIScene] Game paused (menu opened)");
      }
    }
    this.updateMenuStatusDisplays();
    menuOverlay.style.opacity = "0";
    requestAnimationFrame(() => {
      if (menuOverlay) {
        menuOverlay.style.transition = "opacity 0.2s ease";
        menuOverlay.style.opacity = "1";
      }
    });
  }
  /**
   * Close the settings menu
   * AUTO-RESUMES the game when menu closes
   */
  closeMenu() {
    const sceneRoot = OverlayManager.getSceneRoot(this.sceneKey);
    if (!sceneRoot) return;
    const menuOverlay = sceneRoot.querySelector("#menu-overlay");
    if (!menuOverlay) return;
    menuOverlay.style.opacity = "0";
    setTimeout(() => {
      menuOverlay.classList.add("hidden");
      this.isMenuOpen = false;
      if (this.menuButtonElement) {
        this.menuButtonElement.style.display = "flex";
      }
      if (this.currentGameSceneKey) {
        const gameScene = this.scene.get(this.currentGameSceneKey);
        if (gameScene && gameScene.scene.isPaused()) {
          gameScene.scene.resume();
          console.log("[UIScene] Game resumed (menu closed)");
        }
      }
    }, 200);
  }
