        batteryBtn.style.background = "linear-gradient(145deg, rgba(234, 179, 8, 0.85) 0%, rgba(202, 138, 4, 0.8) 100%)";
        batteryBtn.style.borderColor = "rgba(250, 204, 21, 0.6)";
