  updateUI() {
    if (!this.gameScene || !this.gameScene.player) {
      if (this.currentGameSceneKey) {
        const currentScene = this.scene.get(this.currentGameSceneKey);
        if (currentScene && (currentScene.player || currentScene.bossRushMode === true)) {
          this.gameScene = currentScene;
        }
      }
      if (!this.gameScene || !this.gameScene.player && !this.gameScene.bossRushMode) {
        const dungeonScene = this.scene.get("DungeonScene");
        if (dungeonScene && (dungeonScene.player || dungeonScene.bossRushMode === true)) {
          this.gameScene = dungeonScene;
          this.currentGameSceneKey = "DungeonScene";
        }
      }
    }
    if (!this.gameScene) return;
    const sceneRoot = OverlayManager.getSceneRoot(this.sceneKey);
    if (!sceneRoot) return;
    const player = this.gameScene.player;
    if (!player) {
      if (this.gameScene.bossRushMode === true) {
        this.updateBossHPBar(sceneRoot);
      }
      return;
    }
    const healthFill = sceneRoot.querySelector("#health-fill");
    const healthText = sceneRoot.querySelector("#health-text");
    if (healthFill && healthText) {
      healthFill.style.width = `${player.getHealthPercentage()}%`;
      healthText.textContent = `${Math.ceil(player.health)}/${player.maxHealth}`;
    }
    const mobileHealthFill = sceneRoot.querySelector("#mobile-health-fill");
    const mobileHealthText = sceneRoot.querySelector("#mobile-health-text");
    if (mobileHealthFill && mobileHealthText) {
      const healthPercent = player.getHealthPercentage();
      mobileHealthFill.style.width = `${healthPercent}%`;
      mobileHealthText.textContent = `${Math.ceil(player.health)}/${player.maxHealth}`;
      if (healthPercent <= 25) {
        mobileHealthFill.style.background = "linear-gradient(180deg, rgba(255, 100, 100, 1) 0%, rgba(200, 50, 50, 1) 50%, rgba(150, 30, 30, 1) 100%)";
      } else if (healthPercent <= 50) {
        mobileHealthFill.style.background = "linear-gradient(180deg, rgba(255, 180, 100, 1) 0%, rgba(220, 120, 50, 1) 50%, rgba(180, 80, 30, 1) 100%)";
      } else {
        mobileHealthFill.style.background = "linear-gradient(180deg, rgba(248, 113, 113, 1) 0%, rgba(239, 68, 68, 1) 50%, rgba(185, 28, 28, 1) 100%)";
      }
    }
    const leftPanelHpFill = document.getElementById("left-panel-hp-fill");
    const leftPanelHpText = document.getElementById("left-panel-hp-text");
    if (leftPanelHpFill && leftPanelHpText) {
      const healthPercent = player.getHealthPercentage();
      leftPanelHpFill.style.height = `${healthPercent}%`;
      leftPanelHpText.textContent = `${Math.ceil(healthPercent)}%`;
      if (healthPercent <= 25) {
        leftPanelHpFill.style.background = "linear-gradient(180deg, rgba(255, 100, 100, 1) 0%, rgba(200, 50, 50, 1) 50%, rgba(150, 30, 30, 1) 100%)";
        leftPanelHpFill.style.boxShadow = "0 0 15px rgba(255, 50, 50, 0.8)";
      } else if (healthPercent <= 50) {
        leftPanelHpFill.style.background = "linear-gradient(180deg, rgba(255, 180, 100, 1) 0%, rgba(220, 120, 50, 1) 50%, rgba(180, 80, 30, 1) 100%)";
        leftPanelHpFill.style.boxShadow = "0 0 12px rgba(255, 150, 50, 0.6)";
      } else {
        leftPanelHpFill.style.background = "linear-gradient(180deg, rgba(248, 113, 113, 1) 0%, rgba(239, 68, 68, 1) 50%, rgba(185, 28, 28, 1) 100%)";
        leftPanelHpFill.style.boxShadow = "0 0 10px rgba(239, 68, 68, 0.5)";
      }
    }
    const levelText = sceneRoot.querySelector("#level-text");
    if (levelText) {
      levelText.textContent = `Lv. ${player.level}`;
    }
    const goldText = sceneRoot.querySelector("#gold-text");
    if (goldText) {
      goldText.textContent = `${player.gold}`;
    }
    const menuGoldText = sceneRoot.querySelector("#menu-gold-text");
    if (menuGoldText) {
      menuGoldText.textContent = `${player.gold}`;
    }
    this.updateRoundInfo();
    const autoModeContainer = sceneRoot.querySelector("#auto-mode-container");
    const autoModeIndicator = sceneRoot.querySelector("#auto-mode-indicator");
    if (autoModeContainer && autoModeIndicator) {
      const isAutoMode = player.isAutoMode;
      if (isAutoMode) {
        autoModeIndicator.style.backgroundColor = "#22c55e";
        autoModeIndicator.style.boxShadow = "0 0 8px #22c55e";
      } else {
        autoModeIndicator.style.backgroundColor = "#6b7280";
        autoModeIndicator.style.boxShadow = "none";
      }
    }
    const menuAutoStatus = sceneRoot.querySelector("#menu-auto-status");
    if (menuAutoStatus) {
      const isAutoMode = player.isAutoMode;
      if (isAutoMode) {
        menuAutoStatus.textContent = "ON";
        menuAutoStatus.className = "text-green-400 font-bold text-sm";
      } else {
        menuAutoStatus.textContent = "OFF";
        menuAutoStatus.className = "text-gray-400 font-bold text-sm";
      }
    }
    this.updateMinimap();
    this.updateCompassUI(player);
    this.updateQChargeUI(player);
    this.updateDesktopSkillUI(player);
    this.updateBloodFuryUI(player);
    this.updateClassUI(player);
    this.updateAutoExecuteUI(player);
    this.updateEgoLogoTransparency(sceneRoot);
    this.updateBossHPBar(sceneRoot);
  }
  /**
   * Update Compass UI
   * Shows direction and distance to the next portal/objective
   * Only visible when portal is active
   */
  updateCompassUI(player) {
    const sceneRoot = OverlayManager.getSceneRoot(this.sceneKey);
    if (!sceneRoot) return;
    const compassContainer = sceneRoot.querySelector("#compass-container");
    const compassArrow = sceneRoot.querySelector("#compass-arrow");
    const compassDistance = sceneRoot.querySelector("#compass-distance");
    if (!compassContainer || !compassArrow || !compassDistance) return;
    if (this.currentGameSceneKey !== "DungeonScene") {
      compassContainer.style.opacity = "0";
      return;
    }
    const dungeonScene = this.gameScene;
    let targetX = null;
    let targetY = null;
    let targetType = "";
    if (dungeonScene.portalToNextRound && dungeonScene.exitPortalActive) {
      targetX = dungeonScene.portalToNextRound.x;
      targetY = dungeonScene.portalToNextRound.y;
      targetType = "portal";
    } else if (dungeonScene.endingPortal && dungeonScene.endingPortalActive) {
      targetX = dungeonScene.endingPortal.x;
      targetY = dungeonScene.endingPortal.y;
      targetType = "ending";
    } else if (dungeonScene.enemies) {
      const activeBoss = dungeonScene.enemies.children.entries.find(
        (e) => e.active && !e.isDead && (e.isBoss || e.isMiniBoss)
      );
      if (activeBoss) {
        targetX = activeBoss.x;
        targetY = activeBoss.y;
        targetType = "boss";
      }
    }
    if (targetX === null || targetY === null) {
      compassContainer.style.opacity = "0";
      return;
    }
    compassContainer.style.opacity = "1";
    const dx = targetX - player.x;
    const dy = targetY - player.y;
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);
    compassArrow.style.transform = `rotate(${angle}deg)`;
    const distance = Math.sqrt(dx * dx + dy * dy);
    const distanceInMeters = Math.floor(distance / 64);
    if (distanceInMeters > 0) {
      compassDistance.textContent = `${distanceInMeters}m`;
    } else {
      compassDistance.textContent = "Here!";
    }
    const arrowSpan = compassArrow.querySelector("span");
    if (arrowSpan) {
      if (targetType === "boss") {
        arrowSpan.style.color = "#f87171";
        arrowSpan.style.textShadow = "0 0 6px rgba(239, 68, 68, 0.8)";
      } else if (targetType === "ending") {
        arrowSpan.style.color = "#fbbf24";
        arrowSpan.style.textShadow = "0 0 6px rgba(251, 191, 36, 0.8)";
      } else {
        arrowSpan.style.color = "#f0abfc";
        arrowSpan.style.textShadow = "0 0 6px rgba(168, 85, 247, 0.8)";
      }
    }
  }
